private static void addAttachmentAnnotationsToDocument(PDDocument document, List<EmailAttachment> attachments) throws IOException {
    if (document.getNumberOfPages() == 0 || attachments == null || attachments.isEmpty()) {
        return;
    }

    // 1. Find the screen position of all attachment markers
    AttachmentMarkerPositionFinder finder = new AttachmentMarkerPositionFinder();
    finder.setSortByPosition(true); // Process pages in order

    finder.getText(document);
    List<MarkerPosition> markerPositions = finder.getPositions();

    // 2. Warn if the number of markers and attachments don't match
    if (markerPositions.size() != attachments.size()) {
        log.warn("Found {} attachment markers, but there are {} attachments. Annotation count may be incorrect.",
                markerPositions.size(), attachments.size());
    }

    // 3. Create an invisible annotation over each found marker
    int annotationsToAdd = Math.min(markerPositions.size(), attachments.size());

    for (int i = 0; i < annotationsToAdd; i++) {
        MarkerPosition position = markerPositions.get(i);
        EmailAttachment attachment = attachments.get(i);

        if (attachment.getEmbeddedFilename() != null) {
            PDPage page = document.getPage(position.getPageIndex());
            addAttachmentAnnotationToPage(document, page, attachment, position.getX(), position.getY());
        }
    }
}

private ApiResponse processAsyncExecRequest(ApiRequest apiRequest, Session session) {
    String commandLine = apiRequest.getCommand();
    Map<String, Object> body = new TreeMap<String, Object>();

    body.put("command", commandLine);

    ApiResponse response = new ApiResponse();
    response.setSessionId(session.getSessionId()).setBody(body);

    if (!session.tryLock()) {
        response.setState(ApiState.REFUSED).setMessage("Another command is executing.");
        return response;
    }

    int lock = session.getLock();
    try {
        Job foregroundJob = session.getForegroundJob();

        if (foregroundJob != null) {
            response.setState(ApiState.REFUSED).setMessage("Another job is running.");
            logger.info("Another job is running, jobId: {}", foregroundJob.id());
            return response;
        }

        //create job
        Job job = this.createJob(commandLine, session, session.getResultDistributor());
        body.put("jobId", job.id());
        body.put("jobStatus", job.status());
        response.setState(ApiState.SCHEDULED);
        //add command before exec job
        CommandRequestModel commandRequestModel = new CommandRequestModel(commandLine, response.getState());
        commandRequestModel.setJobId(job.id());
        SharingResultDistributor resultDistributor = session.getResultDistributor();
        if (resultDistributor != null) {
            resultDistributor.appendResult(commandRequestModel);
        }
        session.setForegroundJob(job);
        updateSessionInputStatus(session, InputStatus.ALLOW_INTERRUPT);
        //run job
        job.run();
        return response;
    } catch (Throwable e) {
        logger.error("Async exec command failed:" + e.getMessage() + ", command:" + commandLine, e);
        response.setState(ApiState.FAILED).setMessage("Async exec command failed:" + e.getMessage());
        CommandRequestModel commandRequestModel = new CommandRequestModel(commandLine, response.getState(), response.getMessage());
        session.getResultDistributor().appendResult(commandRequestModel);
        return response;
    } finally {
        if (session.getLock() == lock) {
            session.unLock();
        }
    }
}

void drain() {

  if (getAndIncrement() != 0) {
    return;
  }
  int missed = 1;
  EqualObserver<T>[] as = observers;
  final EqualObserver<T> observer1 = as[0];
  final SpscLinkedArrayQueue<T> q1 = observer1.queue;
  final EqualObserver<T> observer2 = as[1];
  final SpscLinkedArrayQueue<T> q2 = observer2.queue;
  for (;;) {
    for (;;) {

      if (cancelled) {
        q1.clear();
        q2.clear();
        return;
      }
      boolean d1 = observer1.done;
      if (d1) {
        Throwable e = observer1.error;
        if (e != null) {
          cancel(q1, q2);
          downstream.onError(e);
          return;
        }
      }
      boolean d2 = observer2.done;
      if (d2) {
        Throwable e = observer2.error;
        if (e != null) {
          cancel(q1, q2);
          downstream.onError(e);
          return;
        }
      }

      if (v1 == null) {
        v1 = q1.poll();
      }
      boolean e1 = v1 == null;
      if (v2 == null) {
        v2 = q2.poll();
      }
      boolean e2 = v2 == null;
      if (d1 && d2 && e1 && e2) {
        downstream.onSuccess(true);
        return;
      }

      if ((d1 && d2) && (e1 != e2)) {
        cancel(q1, q2);
        downstream.onSuccess(false);
        return;
      }

      if (!e1 && !e2) {
        boolean c;
        try {
          c = comparer.test(v1, v2);
        } catch (Throwable ex) {
          Exceptions.throwIfFatal(ex);
          cancel(q1, q2);
          downstream.onError(ex);
          return;
        }
        if (!c) {
          cancel(q1, q2);
          downstream.onSuccess(false);
          return;
        }
        v1 = null;
        v2 = null;
      }

      if (e1) {
        break;
      }

      if (e2) {
        break;
      }
    }
    missed = addAndGet(-missed);
    if (missed == 0) {
      break;
    }
  }
}

