public void run() {
    try {
        while (!stopped) {
            try {
                select();
                processAcceptedConnections();
                processInterestOpsUpdateRequests();
            } catch (RuntimeException e) {
                LOG.warn("Ignoring unexpected runtime exception", e);
            } catch (Exception e) {
                LOG.warn("Ignoring unexpected exception", e);
            }
        }

        // Close connections still pending on the selector. Any others
        // with in-flight work, let drain out of the work queue.
        for (SelectionKey key:selector.keys()) {
            NIOServerCnxn cnxn = (NIOServerCnxn) key.attachment();
            if (cnxn.isSelectable()) {
                cnxn.close(ServerCnxn.DisconnectReason.SERVER_SHUTDOWN);
            }
            cleanupSelectionKey(key);
        }

        SocketChannel accepted;
        while ((accepted = acceptedQueue.poll()) != null) {
            fastCloseSock(accepted);
        }
        updateQueue.clear();
    } finally {
        closeSelector();
        // This will wake up the accept thread and the other selector
        // threads, and tell the worker thread pool to begin shutdown.
        NIOServerCnxnFactory.this.stop();
        LOG.info("selector thread exited run method");
    }
}

private void processRequest(int limitPerDay,
String identifier, Map<String, Bucket> buckets,
HttpServletRequest request,
HttpServletResponse response,
FilterChain filterChain) throws IOException, ServletException {
    Bucket userBucket = buckets.computeIfAbsent(identifier, k -> createUserBucket(limitPerDay));

    ConsumptionProbe probe = userBucket.tryConsumeAndReturnRemaining(1);
    if (probe.isConsumed()) {
        response.setHeader("X-Rate-Limit-Remaining", stripNewlines(Newlines.stripAll(Long.toString(probe.getRemainingTokens()))));
        filterChain.doFilter(request, response);
    } 

    else {
        long waitForRefill = probe.getNanosToWaitForRefill() / 1_000_000_000;
        response.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());
        response.setHeader("X-Rate-Limit-Retry-After-Seconds", Newlines.stripAll(String.valueOf(waitForRefill)));
        response.getWriter().write("Rate limit exceeded for POST requests.");
    }

}

private static void sanitizeHtmlFilesInZip(Path zipFilePath, boolean disableSanitize, TempFileManager tempFileManager) throws IOException {
    try (TempDirectory tempUnzippedDir = new TempDirectory(tempFileManager)) {
        try (ZipInputStream zipIn = 
        ZipSecurity.createHardenedInputStream(
        new ByteArrayInputStream(Files.readAllBytes(zipFilePath)))) {

            ZipEntry entry = zipIn.getNextEntry();
            while (entry != null) {
                Path filePath = tempUnzippedDir.getPath().resolve(sanitizeZipFilename(entry.getName()));
                if (!entry.isDirectory()) {
                    Files.createDirectories(filePath.getParent());
                    if (!(entry.getName().toLowerCase().endsWith(".html") || entry.getName().toLowerCase().endsWith(".htm"))) {
                        Files.copy(zipIn, filePath);
                    } else {
                        String content = new String(zipIn.readAllBytes(), StandardCharsets.UTF_8);

                        String sanitizedContent = sanitizeHtmlContent(content, disableSanitize);
                        Files.write(filePath, sanitizedContent.getBytes(StandardCharsets.UTF_8));
                    } 

                }

                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }

        // Repack the sanitized files
        zipDirectory(tempUnzippedDir.getPath(), zipFilePath);
    } 
// tempUnzippedDir auto-cleaned
}

void drain() {
    if (getAndIncrement() != 0) {
        return;
    }

    int missed = 1;
    Observer<? super R> downstream = this.downstream;
    AtomicThrowable errors = this.errors;
    AtomicReference<SwitchMapMaybeObserver<R>> inner = this.inner;

    for (;;) {

        for (;;) {
            if (cancelled) {
                return;
            }
            if (errors.get() != null && !delayErrors) {
                errors.tryTerminateConsumer(downstream);
                return;
            }

            boolean d = done;
            SwitchMapMaybeObserver<R> current = inner.get();
            boolean empty = current == null;
            if (d && empty) {
                errors.tryTerminateConsumer(downstream);
                return;
            }
            if (empty || current.item == null) {
                break;
            }
            inner.compareAndSet(current, null);
            downstream.onNext(current.item);
        }

        missed = addAndGet(-missed);

        if (missed == 0) {
            break;
        }
    }
}

public static int startArthasClient(String arthasHomeDir, List<String> telnetArgs, OutputStream out) throws Throwable {
  // start java telnet client
  // find arthas-client.jar
  URLClassLoader classLoader = new URLClassLoader(new URL[]{new File(arthasHomeDir, "arthas-client.jar").toURI().toURL()});
  Class<?> telnetConsoleClass = classLoader.loadClass("com.taobao.arthas.client.TelnetConsole");
  Method processMethod = telnetConsoleClass.getMethod("process", String[].class);
  //redirect System.out/System.err
  PrintStream originSysOut = System.out;
  PrintStream originSysErr = System.err;
  PrintStream newOut = new PrintStream(out);
  PrintStream newErr = new PrintStream(out);
  // call TelnetConsole.process()
  // fix https://github.com/alibaba/arthas/issues/833
  ClassLoader tccl = Thread.currentThread().getContextClassLoader();
  try {
    System.setOut(newOut);
    System.setErr(newErr);
    Thread.currentThread().setContextClassLoader(classLoader);

    return (Integer) processMethod.invoke(null, new Object[]{telnetArgs.toArray(new String[0])});
  } catch (Throwable e) {
    //java.lang.reflect.InvocationTargetException : java.net.ConnectException
    e = e.getCause();
    if (e instanceof IOException || e instanceof InterruptedException) {
      // ignore connection error and interrupted error
      return STATUS_ERROR;
    } else {
      // process error
      AnsiLog.error("process error: {}", e.toString());
      AnsiLog.error(e);
      return STATUS_EXEC_ERROR;
    }
  } finally {
    Thread.currentThread().setContextClassLoader(tccl);
    //reset System.out/System.err
    System.setOut(originSysOut);
    System.setErr(originSysErr);
    //flush output
    newOut.flush();
    newErr.flush();
  }
}

