@Produces( { MediaType.APPLICATION_JSON, "application/javascript",
MediaType.APPLICATION_XML })
public Response createSession(@QueryParam("op") String op,@DefaultValue("5") @QueryParam("expire") String expire,@Context UriInfo ui) {
    if (!op.equals("create")) {
        throw new WebApplicationException(Response.status(Response.Status.BAD_REQUEST).entity(new ZError(ui.getRequestUri().toString(), "")).build());
    }

    int expireInSeconds;
    try {
        expireInSeconds = Integer.parseInt(expire);
    } catch (NumberFormatException e) {
        throw new WebApplicationException(Response.status(Response.Status.BAD_REQUEST).build());
    }

    String uuid = UUID.randomUUID().toString();
    while (ZooKeeperService.isConnected(contextPath, uuid)) {
        uuid = UUID.randomUUID().toString();
    }

    // establish the connection to the ZooKeeper cluster
    try {
        ZooKeeperService.getClient(contextPath, uuid, expireInSeconds);
    } catch (IOException e) {
        LOG.error("Failed while trying to create a new session", e);
        throw new WebApplicationException(Response.status(Response.Status.INTERNAL_SERVER_ERROR).build());
    }

    URI uri = ui.getAbsolutePathBuilder().path(uuid).build();
    return Response.created(uri).entity(new JSONWithPadding(new ZSession(uuid, uri.toString()))).build();
}

private static void handleError(final Context context, final ErrorInfo errorInfo) {
    if (errorInfo.getThrowable() != null) {
        errorInfo.getThrowable().printStackTrace();
    }

    if (errorInfo.getThrowable() instanceof ReCaptchaException) {
        Toast.makeText(context, R.string.recaptcha_request_toast, Toast.LENGTH_LONG).show();

        // Starting ReCaptcha Challenge Activity
        final Intent intent = new Intent(context, ReCaptchaActivity.class);
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        context.startActivity(intent);
    } else if (!(errorInfo.getThrowable() != null && ExceptionUtils.isNetworkRelated(errorInfo.getThrowable()))) {
        if (errorInfo.getThrowable() 
             instanceof AgeRestrictedContentException) {
            Toast.makeText(context, R.string.restricted_video_no_stream, Toast.LENGTH_LONG).show();
        } else if (!(errorInfo.getThrowable() instanceof GeographicRestrictionException)) {
            if (errorInfo.getThrowable() 
                 instanceof PaidContentException) {
                Toast.makeText(context, R.string.paid_content, Toast.LENGTH_LONG).show();
            } else if (!(errorInfo.getThrowable() instanceof PrivateContentException)) {
                if (!(errorInfo.getThrowable() 
                     instanceof SoundCloudGoPlusContentException)) {
                    if (errorInfo.getThrowable() 
                         instanceof YoutubeMusicPremiumContentException) {
                        Toast.makeText(context, R.string.youtube_music_premium_content, Toast.LENGTH_LONG).show();
                    } else if (!(errorInfo.getThrowable() instanceof ContentNotAvailableException)) {
                        if (errorInfo.getThrowable() 
                             instanceof ContentNotSupportedException) {
                            Toast.makeText(context, R.string.content_not_supported, Toast.LENGTH_LONG).show();
                        } else {
                            ErrorUtil.createNotification(context, errorInfo);
                        }
                    } else {
                        Toast.makeText(context, R.string.content_not_available, Toast.LENGTH_LONG).show();
                    }
                } else {
                    Toast.makeText(context, R.string.soundcloud_go_plus_content, Toast.LENGTH_LONG).show();
                }
            } else {
                Toast.makeText(context, R.string.private_content, Toast.LENGTH_LONG).show();
            }
        } else {
            Toast.makeText(context, R.string.georestricted_content, Toast.LENGTH_LONG).show();
        }
    } else {
        Toast.makeText(context, R.string.network_error, Toast.LENGTH_LONG).show();
    } 


    if (context instanceof RouterActivity) {
        ((RouterActivity) context).finish();
    }
}

private void doPostprocessing() {
    errCode = ERROR_NOTHING;

    errObject = null;

    Thread thread = Thread.currentThread();
    notifyPostProcessing(1);
    if (DEBUG) {
        thread.setName("[" + TAG + "]  ps = " + psAlgorithm + "  filename = " + storage.getName());
    }

    Exception exception = null;
    try {
        psAlgorithm.run(this);
    } catch (Exception err) {
        Log.e(TAG, "Post-processing failed. " + psAlgorithm.toString(), err);
        if (err instanceof InterruptedIOException || err instanceof ClosedByInterruptException || thread.isInterrupted()) {
            notifyError(DownloadMission.ERROR_POSTPROCESSING_STOPPED, null);

            return;
        }

        if (errCode == ERROR_NOTHING) {
            errCode = ERROR_POSTPROCESSING;
        }
        exception = err;
    } finally {
        notifyPostProcessing(errCode == ERROR_NOTHING ? 2 : 0);
    }

    if (errCode != ERROR_NOTHING) {
        if (exception == null) {
            exception = errObject;
        }
        notifyError(ERROR_POSTPROCESSING, exception);

        return;
    }
    notifyFinished();
}

public void schedule(WorkRequest workRequest, long id) {
    if (stopped) {
        workRequest.cleanup();
        return;
    }

    ScheduledWorkRequest scheduledWorkRequest = new ScheduledWorkRequest(workRequest);
    // If we have a worker thread pool, use that; otherwise, do the work
    // directly.
    int size = workers.size();
    if (size <= 0) {
        // When there is no worker thread pool, do the work directly
        // and wait for its completion
        scheduledWorkRequest.run();
    } else {
        try {
            // make sure to map negative ids as well to [0, size-1]
            int workerNum = ((int) (id % size) + size) % size;
            ExecutorService worker = workers.get(workerNum);
            worker.execute(scheduledWorkRequest);
        } catch (RejectedExecutionException e) {
            LOG.warn("ExecutorService rejected execution", e);
            workRequest.cleanup();
        }
    } 
}
